1	//! The layer's one record of the dependency files it could not read, and of what those reads left unfollowed.
2	//!
3	//! A read that fails is unknown, not absent ([`ReadFailed`]). Every decision that depends on one asks this ledger: the
4	//! warnings a layer reports (one per file whose latest read failed), which demands a load follows again, which answers
5	//! a lazy session may memoize, and whether a cold load may write the index. Nothing else holds the fact.
6	//!
7	//! Reads are keyed by path, and marks by the node of the walk that met the failure: a demand, or a declaration it
8	//! claimed. A mark is what a follow found, so a later read of the same file by another walk does not clear it: only
9	//! following that demand again does. Each layer holds only what changed since the layer below; lookups take the newest
10	//! entry in the chain, and a flatten merges the chain's ledgers the same way.
11	//!
12	//! A file that stays unreadable (permissions, a broken install) would otherwise make every request follow its walk
13	//! again, and pay a load and a resolution for it. A lazy session follows one again only once it is due ([`Retry`]): a
14	//! file its own walk could not read was read since, [`READ_RETRY`] passed since that read failed, or an edit arrived.
15	//! Deciding that touches no file: a file that changes on disk is read again at the retry or the next edit.
16	
17	use std::time::{Duration, Instant};
18	
19	use super::*;
20	
21	/// How long a walk that passed a file it could not read is answered from what it read, before a request that reaches
22	/// it follows it again; the checker side's `DEGRADED_RETRY` holds a degraded answer as long.
23	pub(crate) const READ_RETRY: Duration = Duration::from_secs(30);
24	
25	/// When a load follows again a walk that passed a file it could not read.
26	#[derive(Clone, Copy, Debug)]
27	pub(crate) enum Retry {
28	    /// Every such walk: a caller that follows on each change (watch's eager revisions, a cold run).
29	    Always,
30	    /// Once it is due: a file its walk could not read was read since, [`READ_RETRY`] passed since that read failed, or
31	    /// an edit arrived since (`edits`, the session's count of them, moved past the failure's).
32	    Due { now: Instant, edits: u64, load: u64 },
33	}
34	
35	/// A read that failed, and when.
36	#[derive(Clone, Debug)]
37	struct FailedRead {
38	    warning: Diagnostic,
39	    at: Instant,
40	    edits: u64,
41	    /// The load that made this read, so a [`Footprint`] tells it from a later failure of the same file.
42	    load: u64,
43	}
44	
45	impl FailedRead {
46	    /// When a walk that met this failure is due again by time; `None` when an edit since already made it due.
47	    fn retry_at(&self, edits: u64) -> Option<Instant> {
48	        (self.edits >= edits).then(|| self.at + READ_RETRY)
49	    }
50	}
51	
52	/// A declaration a load claimed: `(file, name)`.
53	pub(super) type ClaimKey = (PathKey, CompactString);
54	
55	/// A node of the walk a load makes: a demand, or a declaration one claimed, whose references it followed.
56	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
57	pub(super) enum Node {
58	    Demand(DemandKey),
59	    Claim(ClaimKey),
60	}
61	
62	/// The latest read of one dependency file in the chain, kept only once a read of it failed.
63	#[derive(Clone, Debug)]
64	enum Read {
65	    /// Read, or found missing, after an earlier read failed: what it declares is known again.
66	    Done,
67	    /// The file exists but could not be read; the warning reports it.
68	    Failed(FailedRead),
69	}
70	
71	/// What the latest follow of a node left unread. A node with no mark in the chain reached nothing unread.
72	#[derive(Clone, Debug, Default)]
73	struct Mark {
74	    /// The demand's own walk passed a file it could not read: following it again may answer more.
75	    unread: Option<Demand>,
76	    /// The files the demand's own walk could not read, the last time it was followed.
77	    suspects: Box<[PathKey]>,
78	    /// The marked nodes it reached: below it in the same load, or marked by an earlier one.
79	    reaches: Box<[Node]>,
80	}
81	
82	impl Mark {
83	    fn is_clean(&self) -> bool {
84	        self.unread.is_none() && self.reaches.is_empty()
85	    }
86	
87	    /// Whether a load under `retry` follows this mark's demand again: its own walk is unread and that is due.
88	    fn is_due<'a>(&self, retry: Retry, latest: impl Fn(&str) -> Option<&'a Read>) -> bool {
89	        if self.unread.is_none() {
90	            return false;
91	        }
92	        let Retry::Due { now, edits, .. } = retry else { return true };
93	        self.retry_at(edits, latest).is_none_or(|at| at <= now)
94	    }
95	
96	    /// When this mark's unread walk is due by time, the earliest of its files' retries; `None` when it is due already
97	    /// whatever the time: an edit arrived since a failure, or one of its files was read since.
98	    fn retry_at<'a>(&self, edits: u64, latest: impl Fn(&str) -> Option<&'a Read>) -> Option<Instant> {
99	        let mut earliest: Option<Instant> = None;
100	        for path in &self.suspects {
101	            let at = match latest(std::borrow::Borrow::borrow(path)) {
102	                Some(Read::Failed(failed)) => failed.retry_at(edits)?,
103	                Some(Read::Done) | None => return None,
104	            };
105	            earliest = Some(earliest.map_or(at, |earliest| earliest.min(at)));
106	        }
107	        earliest
108	    }
109	}
110	
111	/// The walks of a chain that are unread, and what reached them: what was read through these may lack what the files
112	/// they could not read hold ([`DependencyLayer::unread_walks`]).
113	#[derive(Default)]
114	pub(crate) struct UnreadWalks {
115	    demands: FxHashSet<DemandKey>,
116	    /// The files of the declarations whose references reach an unread walk.
117	    files: FxHashSet<PathKey>,
118	    /// The files whose latest read failed.
119	    failed: FxHashSet<PathKey>,
120	}
121	
122	impl UnreadWalks {
123	    pub(crate) fn is_empty(&self) -> bool {
124	        self.demands.is_empty() && self.files.is_empty() && self.failed.is_empty()
125	    }
126	
127	    /// Whether one of `demands` (a project file's) reached an unread walk: what was read through it may lack what that
128	    /// walk would have given.
129	    pub(crate) fn reached_by(&self, demands: &[Demand]) -> bool {
130	        demands.iter().any(|demand| self.demands.contains(&demand.key()))
131	    }
132	
133	    /// Whether a declaration in the package file `file` reached an unread walk.
134	    pub(crate) fn declared_in(&self, file: &str) -> bool {
135	        self.files.contains(file)
136	    }
137	
138	    /// Whether what was read in `file` may change once a walk that could not read a file is followed again: a
139	    /// declaration in it reached an unread walk, or it is itself a file whose latest read failed.
140	    pub(crate) fn touches(&self, file: &str) -> bool {
141	        self.files.contains(file) || self.failed.contains(file)
142	    }
143	}
144	
145	/// What a provisional answer read through unread walks ([`DependencyLayer::footprint`]): each file those walks could
146	/// not read, with the load, time and edit count of the failed read the answer saw. The one rule for every answer
147	/// resolved past a file that could not be read: it holds while each of these is still that failed read and not due
148	/// ([`DependencyLayer::footprint_holds`]), and not a moment after.
149	#[derive(Clone, Debug, PartialEq, Eq)]
150	pub(crate) struct Footprint(Box<[(PathKey, u64, Instant, u64)]>);
151	
152	/// One layer's entries: what its load read again or could not read, and the marks its follows left.
153	#[derive(Default)]
154	pub(super) struct ReadLedger {
155	    reads: FxHashMap<PathKey, Read>,
156	    marks: FxHashMap<Node, Mark>,
157	}
158	
159	impl ReadLedger {
160	    /// `newer`'s entries over this ledger's, as a flatten merges a chain: the latest entry wins.
161	    fn absorb(&mut self, newer: &ReadLedger) {
162	        self.reads.extend(newer.reads.iter().map(|(path, read)| (path.clone(), read.clone())));
163	        self.marks.extend(newer.marks.iter().map(|(node, mark)| (node.clone(), mark.clone())));
164	    }
165	}
166	
167	/// The demands whose own walk is unread, among `start` and the nodes their marks reach, sorted.
168	fn unread_below<'a>(start: impl IntoIterator<Item = Node>, mark: impl Fn(&Node) -> Option<&'a Mark>) -> Vec<Demand> {
169	    let mut found: Vec<Demand> = Vec::new();
170	    let mut seen: FxHashSet<Node> = FxHashSet::default();
171	    let mut stack: Vec<Node> = start.into_iter().collect();
172	    while let Some(node) = stack.pop() {
173	        let Some(marked) = mark(&node) else { continue };
174	        if !seen.insert(node) {
175	            continue;
176	        }
177	        found.extend(marked.unread.iter().cloned());
178	        stack.extend(marked.reaches.iter().cloned());
179	    }
180	    found.sort();
181	    found.dedup();
182	    found
183	}
184	
185	impl DependencyLayer {
186	    fn has_marks(&self) -> bool {
187	        self.chain().any(|layer| !layer.ledger.marks.is_empty())
188	    }
189	
190	    fn latest_read(&self, file: &str) -> Option<&Read> {
191	        self.chain().find_map(|layer| layer.ledger.reads.get(file))
192	    }
193	
194	    fn mark(&self, node: &Node) -> Option<&Mark> {
195	        self.chain().find_map(|layer| layer.ledger.marks.get(node))
196	    }
197	
198	    /// Whether the latest read of `file` in the chain failed.
199	    fn read_failed(&self, file: &str) -> bool {
200	        matches!(self.latest_read(file), Some(Read::Failed(_)))
201	    }
202	
203	    /// One warning for each file whose latest read in the chain failed, sorted by message.
204	    pub(crate) fn read_warnings(&self) -> Vec<Diagnostic> {
205	        let mut seen: FxHashSet<&PathKey> = FxHashSet::default();
206	        let mut warnings: Vec<Diagnostic> = Vec::new();
207	        for layer in self.chain() {
208	            for (path, read) in &layer.ledger.reads {
209	                if seen.insert(path)
210	                    && let Read::Failed(failed) = read
211	                {
212	                    warnings.push(failed.warning.clone());
213	                }
214	            }
215	        }
216	        warnings.sort_by(|a, b| (&a.message, &a.file).cmp(&(&b.message, &b.file)));
217	        warnings
218	    }
219	
220	    /// Whether the demand's own walk passed a file it could not read, the last time the chain followed it, and a load
221	    /// under `retry` follows it again.
222	    pub(super) fn awaits_retry(&self, key: &DemandKey, retry: Retry) -> bool {
223	        self.has_marks()
224	            && self
225	                .mark(&Node::Demand(key.clone()))
226	                .is_some_and(|mark| mark.is_due(retry, |path| self.latest_read(path)))
227	    }
228	
229	    /// The footprint of an answer resolved through the unread walks `unread` ([`Self::unread`]): every file those
230	    /// walks could not read, with the failed read the answer saw. `None` when one of them is no longer unread.
231	    pub(crate) fn footprint(&self, unread: &[Demand]) -> Option<Footprint> {
232	        let mut files: Vec<(PathKey, u64, Instant, u64)> = Vec::new();
233	        for demand in unread {
234	            let mark = self.mark(&Node::Demand(demand.key())).filter(|mark| mark.unread.is_some())?;
235	            for path in &mark.suspects {
236	                let Some(Read::Failed(failed)) = self.latest_read(std::borrow::Borrow::borrow(path)) else {
237	                    return None;
238	                };
239	                files.push((path.clone(), failed.load, failed.at, failed.edits));
240	            }
241	        }
242	        files.sort_by(|a, b| a.0.cmp(&b.0));
243	        files.dedup_by(|a, b| a.0 == b.0);
244	        (!files.is_empty()).then(|| Footprint(files.into_boxed_slice()))
245	    }
246	
247	    /// Whether an answer with `footprint` still holds: every file in it is still the failed read the answer saw (no
248	    /// load read it since, whichever walk), its retry has not passed, and no edit arrived since.
249	    pub(crate) fn footprint_holds(&self, footprint: &Footprint, now: Instant, edits: u64) -> bool {
250	        footprint.0.iter().all(|(path, load, at, failed_edits)| {
251	            let same = matches!(self.latest_read(std::borrow::Borrow::borrow(path)),
252	                Some(Read::Failed(failed)) if failed.load == *load && failed.at == *at);
253	            same && *failed_edits >= edits && now < *at + READ_RETRY
254	        })
255	    }
256	
257	    /// How many files each of this layer's own unread walks holds, for tests.
258	    #[cfg(test)]
259	    pub(crate) fn suspect_counts(&self) -> Vec<usize> {
260	        self.ledger.marks.values().filter(|mark| mark.unread.is_some()).map(|mark| mark.suspects.len()).collect()
261	    }
262	
263	    /// Every node of the chain whose latest follow reached a walk that is unread, its own or one below it.
264	    pub(crate) fn unread_walks(&self) -> UnreadWalks {
265	        self.unread_walks_counted().0
266	    }
267	
268	    /// [`Self::unread_walks`], and how many nodes its traversal visited: one reverse traversal from the unread walks
269	    /// over the latest marks, each node once, so a chain of N declarations ending at one unread file costs N.
270	    pub(crate) fn unread_walks_counted(&self) -> (UnreadWalks, usize) {
271	        let mut walks = UnreadWalks::default();
272	        if !self.has_marks() {
273	            return (walks, 0);
274	        }
275	        let mut latest: FxHashMap<&Node, &Mark> = FxHashMap::default();
276	        for layer in self.chain() {
277	            for (node, mark) in &layer.ledger.marks {
278	                latest.entry(node).or_insert(mark);
279	            }
280	            for (path, read) in &layer.ledger.reads {
281	                if self.latest_read(std::borrow::Borrow::borrow(path)).is_some_and(|latest| std::ptr::eq(latest, read))
282	                    && matches!(read, Read::Failed(_))
283	                {
284	                    walks.failed.insert(path.clone());
285	                }
286	            }
287	        }
288	        let mut reached_by: FxHashMap<&Node, Vec<&Node>> = FxHashMap::default();
289	        let mut marked: FxHashSet<&Node> = FxHashSet::default();
290	        let mut queue: Vec<&Node> = Vec::new();
291	        for (&node, mark) in &latest {
292	            for to in mark.reaches.iter() {
293	                reached_by.entry(to).or_default().push(node);
294	            }
295	            if mark.unread.is_some() && marked.insert(node) {
296	                queue.push(node);
297	            }
298	        }
299	        let mut visits = 0;
300	        while let Some(node) = queue.pop() {
301	            visits += 1;
302	            for &from in reached_by.get(node).into_iter().flatten() {
303	                if marked.insert(from) {
304	                    queue.push(from);
305	                }
306	            }
307	        }
308	        for node in marked {
309	            match node {
310	                Node::Demand(key) => walks.demands.insert(key.clone()),
311	                Node::Claim((file, _)) => walks.files.insert(file.clone()),
312	            };
313	        }
314	        (walks, visits)
315	    }
316	
317	    /// The demands that `roots` lead to, themselves included, whose walk passed a file that could not be read and has
318	    /// not been followed since, sorted. Following them again is what may answer more; while there are any, what was
319	    /// resolved from `roots` holds for one request only.
320	    pub(crate) fn unread(&self, roots: &[Demand]) -> Vec<Demand> {
321	        if !self.has_marks() {
322	            return Vec::new();
323	        }
324	        unread_below(roots.iter().map(|demand| Node::Demand(demand.key())), |node| self.mark(node))
325	    }
326	}
327	
328	/// The ledger one load builds as it reads and walks; [`LedgerBuilder::finish`] makes the layer's.
329	pub(super) struct LedgerBuilder<'a> {
330	    parent: Option<&'a DependencyLayer>,
331	    /// The chain a flatten took in, merged: consulted as a parent is.
332	    inherited: ReadLedger,
333	    reads: FxDashMap<PathKey, Read>,
334	    /// Each node this load followed, with the nodes it reached: the demands it spawned or met, the declarations it
335	    /// claimed or met claimed.
336	    edges: FxDashMap<Node, Vec<Node>>,
337	    /// The demands whose own walk passed a file it could not read, with those files.
338	    unread: FxDashMap<DemandKey, (Demand, Vec<PathKey>)>,
339	    /// The demands followed again because their last walk was unread.
340	    retried: FxDashSet<DemandKey>,
341	    /// When this load follows again a demand an earlier one left unread, and the time and edit count its failed reads
342	    /// are recorded at.
343	    pub(super) retry: Retry,
344	}
345	
346	impl<'a> LedgerBuilder<'a> {
347	    pub(super) fn new(parent: Option<&'a DependencyLayer>) -> Self {
348	        LedgerBuilder {
349	            retry: Retry::Always,
350	            parent,
351	            inherited: ReadLedger::default(),
352	            reads: DashMap::default(),
353	            edges: DashMap::default(),
354	            unread: DashMap::default(),
355	            retried: DashSet::default(),
356	        }
357	    }
358	
359	    /// Take in a layer of the chain a flatten replaces; called oldest first.
360	    pub(super) fn inherit(&mut self, layer: &ReadLedger) {
361	        self.inherited.absorb(layer);
362	    }
363	
364	    fn earlier_mark(&self, node: &Node) -> Option<&Mark> {
365	        self.inherited.marks.get(node).or_else(|| self.parent.and_then(|parent| parent.mark(node)))
366	    }
367	
368	    fn has_earlier_marks(&self) -> bool {
369	        !self.inherited.marks.is_empty() || self.parent.is_some_and(DependencyLayer::has_marks)
370	    }
371	
372	    /// `file` was read, or found missing. Recorded only over an earlier failure, which it ends; within one load a
373	    /// failure stands, since the walk that met it is unread.
374	    pub(super) fn read_done(&self, file: &Utf8Path) {
375	        let earlier = match self.inherited.reads.get(file.as_str()) {
376	            Some(read) => matches!(read, Read::Failed(_)),
377	            None => self.parent.is_some_and(|parent| parent.read_failed(file.as_str())),
378	        };
379	        if earlier {
380	            self.reads.entry(PathKey::from(file)).or_insert(Read::Done);
381	        }
382	    }
383	
384	    pub(super) fn read_failed(&self, file: &Utf8Path, warning: Diagnostic) {
385	        let (at, edits, load) = match self.retry {
386	            Retry::Always => (Instant::now(), 0, 0),
387	            Retry::Due { now, edits, load } => (now, edits, load),
388	        };
389	        self.reads.insert(PathKey::from(file), Read::Failed(FailedRead { warning, at, edits, load }));
390	    }
391	
392	    /// `from` reached `to`, whether it followed `to` itself or found it followed already.
393	    pub(super) fn reached(&self, from: &Node, to: Node) {
394	        self.edges.entry(from.clone()).or_default().push(to);
395	    }
396	
397	    /// `demand`'s own walk could not read `files`.
398	    pub(super) fn unread_demand(&self, demand: &Demand, mut files: Vec<PathKey>) {
399	        files.sort();
400	        files.dedup();
401	        self.unread.insert(demand.key(), (demand.clone(), files));
402	    }
403	
404	    /// Whether a demand followed before this load is to be followed again (its last walk was unread and the retry is
405	    /// due), and this is the first time this load meets it.
406	    pub(super) fn retries(&self, key: &DemandKey) -> bool {
407	        let latest = |path: &str| {
408	            self.inherited.reads.get(path).or_else(|| self.parent.and_then(|parent| parent.latest_read(path)))
409	        };
410	        let due = self.has_earlier_marks()
411	            && self.earlier_mark(&Node::Demand(key.clone())).is_some_and(|mark| mark.is_due(self.retry, latest));
412	        due && self.retried.insert(key.clone())
413	    }
414	
415	    /// The layer's ledger. A node this load followed is marked when it reached an unread walk: its own, one below it
416	    /// in this load, or one an earlier load marked that has not been followed since. A demand followed again that
417	    /// reached none is marked clean, over its earlier mark. A ledger with no parent stands alone, so the chain it took
418	    /// in is merged into it and what is clean is dropped.
419	    pub(super) fn finish(self) -> ReadLedger {
420	        let has_earlier = self.has_earlier_marks();
421	        let LedgerBuilder { parent, inherited, reads, edges, unread, retried, retry: _ } = self;
422	        let reads: FxHashMap<PathKey, Read> = reads.into_iter().collect();
423	        let earlier = |node: &Node| inherited.marks.get(node).or_else(|| parent.and_then(|parent| parent.mark(node)));
424	        let unread: FxHashMap<Node, (Demand, Vec<PathKey>)> =
425	            unread.into_iter().map(|(key, walk)| (Node::Demand(key), walk)).collect();
426	        let mut marks: FxHashMap<Node, Mark> = FxHashMap::default();
427	        if !unread.is_empty() || has_earlier {
428	            let edges: FxHashMap<Node, Vec<Node>> = edges.into_iter().collect();
429	            let followed = |node: &Node| {
430	                edges.contains_key(node)
431	                    || unread.contains_key(node)
432	                    || matches!(node, Node::Demand(key) if retried.contains(key))
433	            };
434	            // The walks that are unread: this load's own, and the earlier ones this load met without following.
435	            let mut marked: FxHashSet<&Node> = unread.keys().collect();
436	            let mut queue: Vec<&Node> = marked.iter().copied().collect();
437	            let mut reached_by: FxHashMap<&Node, Vec<&Node>> = FxHashMap::default();
438	            for (from, tos) in &edges {
439	                for to in tos {
440	                    reached_by.entry(to).or_default().push(from);
441	                    if !followed(to)
442	                        && !marked.contains(to)
443	                        && earlier(to).is_some()
444	                        && !unread_below([to.clone()], earlier).is_empty()
445	                    {
446	                        marked.insert(to);
447	                        queue.push(to);
448	                    }
449	                }
450	            }
451	            while let Some(node) = queue.pop() {
452	                for &from in reached_by.get(node).into_iter().flatten() {
453	                    if marked.insert(from) {
454	                        queue.push(from);
455	                    }
456	                }
457	            }
458	            for &node in marked.iter().filter(|node| followed(node)) {
459	                let reaches = edges.get(node).into_iter().flatten().filter(|to| marked.contains(to)).cloned().collect();
460	                let (own, suspects) = match unread.get(node) {
461	                    Some((demand, files)) => (Some(demand.clone()), files.clone().into_boxed_slice()),
462	                    None => (None, Box::default()),
463	                };
464	                marks.insert(node.clone(), Mark { unread: own, suspects, reaches });
465	            }
466	            for key in retried {
467	                marks.entry(Node::Demand(key)).or_default();
468	            }
469	        }
470	        if parent.is_some() {
471	            return ReadLedger { reads, marks };
472	        }
473	        let mut merged = inherited;
474	        merged.absorb(&ReadLedger { reads, marks });
475	        merged.reads.retain(|_, read| matches!(read, Read::Failed(_)));
476	        merged.marks.retain(|_, mark| !mark.is_clean());
477	        merged
478	    }
479	}
480	
481	#[cfg(test)]
482	mod tests;
