140	/// rest once instead of growing for every new component. Tests use a small project, so a small count.
141	const WHOLE_DEMAND_AFTER_GROWTHS: usize = 3;
142	
143	pub(super) struct Lazy {
144	    /// Each project file's dependency demands; files that demand nothing are absent.
145	    demands: FxHashMap<PathKey, Arc<[Demand]>>,
146	    /// Components by name, in output order, with their position in `GlobalSourceData::component_mappings`.
147	    by_name: FxHashMap<String, Vec<(ComponentId, usize)>>,
148	    memo: DashMap<ComponentId, Arc<Resolved>, FxBuildHasher>,
149	    engine: ArcSwap<Engine>,
150	    /// Serializes layer growth, so concurrent requests load a name once.
151	    growing: Mutex<()>,
152	    /// Whether the background load of every name the project takes from a package has started.
153	    whole_demand_started: std::sync::atomic::AtomicBool,
154	    /// The thread loading them, until [`Revision::wait_for_dependency_load`] joins it.
155	    whole_demand_thread: Mutex<Option<std::thread::JoinHandle<()>>>,
156	    /// How many times the layer grew (and the context was rebuilt or kept), for tests and stats.
157	    growths: std::sync::atomic::AtomicUsize,
158	    /// Components resolved through a walk that passed a file it could not read, with the unread walks they reached:
159	    /// answered until one of those is due, then resolved again. Never carried to the next revision, never persisted.
160	    provisional: DashMap<ComponentId, (Arc<Resolved>, dependency_types::Footprint), FxBuildHasher>,
161	    /// The id of the session's next dependency load, shared by its revisions: a footprint tells one load's failed read
162	    /// from a later one's.
163	    load_ids: Arc<std::sync::atomic::AtomicU64>,
164	    /// The session's clock for following again a walk that passed a file it could not read, shared by its revisions.
165	    clock: Arc<RetryClock>,
166	    /// How many edits the session has seen: one arriving makes every such walk due again.
167	    edits: u64,
168	    /// How many times a component was resolved, for tests.
169	    #[cfg(test)]
170	    resolutions: std::sync::atomic::AtomicUsize,
171	    /// How many times the layer was loaded, whether or not it grew, for tests.
172	    #[cfg(test)]
173	    loads: std::sync::atomic::AtomicUsize,
174	    /// Run once by the next [`Revision::lazy_component`] between its resolution and its diagnostics, for tests.
175	    #[cfg(test)]
176	    between: Mutex<Option<Between>>,
177	}
