207	/// The components of `global` by name, each name's components in output order.
208	fn group_by_name(global: &GlobalSourceData, options: &PipelineOptions) -> FxHashMap<String, Vec<(ComponentId, usize)>> {
209	    let mut by_name: FxHashMap<String, Vec<(ComponentId, usize)>> = FxHashMap::default();
210	    for (id, index) in ordered_ids(global, options) {
211	        by_name.entry(id.name.clone()).or_default().push((id, index));
212	    }
213	    by_name
214	}
