216	fn demands_by_file(file_demands: Vec<(Utf8PathBuf, Vec<Demand>)>) -> FxHashMap<PathKey, Arc<[Demand]>> {
217	    file_demands
218	        .into_iter()
219	        .filter(|(_, demands)| !demands.is_empty())
220	        .map(|(file, demands)| (PathKey::from(file.as_path()), Arc::from(demands)))
221	        .collect()
222	}
