224	impl Revision {
225	    /// Discover, parse and merge every source file, and nothing more.
226	    pub(crate) fn cold_lazy(options: &PipelineOptions, id: u64) -> Revision {
227	        let Indexed {
228	            start,
229	            cache,
230	            src_files,
231	            global,
232	            head_diagnostics,
233	            file_diagnostics,
234	            mut lib_diagnostics,
235	            react_types,
236	            file_demands,
237	        } = Indexed::build(options);
238	        let global = Arc::new(global);
239	        let named_types = Arc::new(NamedTypeIndex::build(&global));
240	        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
241	        // The layer starts with the names the project takes from React. A batch run loads them for every component,
242	        // and loading them follows React's own imports (csstype), which any component's HTML attributes can reach
243	        // without its file naming them; a component's answer would otherwise depend on what was asked before it.
244	        // It also reads the persisted dependency index, so names a batch run already resolved cost no walk. The modules
245	        // the project imports start loaded as well: what they merge into React's interfaces reaches every component.
246	        let react: Vec<Demand> = file_demands
247	            .iter()
248	            .flat_map(|(_, demands)| {
249	                demands.iter().filter(|demand| &*demand.specifier == "react" || demand.name.is_empty()).cloned()
250	            })
251	            .collect();
252	        let layer = options.load_dependencies.then(|| Arc::new(dependency_types::load(react, options, None)));
253	        let engine = Engine::new(&global, options, &ambient_global_files, &named_types, layer, &react_types);
254	        lib_diagnostics.extend(engine.ctx.tsconfig_diagnostic.clone());
255	        let (dts_files_parsed, dts_cache_hits) = cache.counts();
256	        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
257	            Ok(c) => c.save_to_disk(),
258	            Err(arc) => arc.save_to_disk(),
259	        }
260	        .into_iter()
261	        .collect();
262	        let lazy = Lazy {
263	            demands: demands_by_file(file_demands),
264	            by_name: group_by_name(&global, options),
265	            memo: DashMap::default(),
266	            engine: ArcSwap::from_pointee(engine),
267	            growing: Mutex::new(()),
268	            whole_demand_started: std::sync::atomic::AtomicBool::new(false),
269	            whole_demand_thread: Mutex::new(None),
270	            growths: std::sync::atomic::AtomicUsize::new(0),
271	            provisional: DashMap::default(),
272	            clock: Arc::default(),
273	            edits: 0,
274	            load_ids: Arc::new(std::sync::atomic::AtomicU64::new(1)),
275	            #[cfg(test)]
276	            resolutions: std::sync::atomic::AtomicUsize::new(0),
277	            #[cfg(test)]
278	            loads: std::sync::atomic::AtomicUsize::new(0),
279	            #[cfg(test)]
280	            between: Mutex::new(None),
281	        };
282	        Revision {
283	            id,
284	            global,
285	            named_types,
286	            dependencies: None,
287	            react_types,
288	            ambient_global_files,
289	            head_diagnostics,
290	            file_diagnostics,
291	            lib_diagnostics,
292	            tail_diagnostics,
293	            resolved: FxHashMap::default(),
294	            sites: Arc::default(),
295	            files: Arc::new(src_files.into_iter().collect()),
296	            dts_files_parsed,
297	            dts_cache_hits,
298	            duration_ms: start.elapsed().as_millis() as u64,
299	            output: Arc::new(empty_output()),
300	            keys: FxHashMap::default(),
301	            lazy: Some(lazy),
302	        }
303	    }
304	
305	    pub(crate) fn is_lazy(&self) -> bool {
306	        self.lazy.is_some()
307	    }
308	
309	    /// The component an eager revision published under `key`, as a lazy revision answers for it.
310	    pub(crate) fn published_component(&self, key: &str) -> Option<ComponentAnswer> {
311	        let entry = self.output.components.get(key)?.clone();
312	        let diagnostics = self
313	            .output
314	            .diagnostics
315	            .iter()
316	            .filter(|diagnostic| diagnostic.affects.iter().any(|affected| affected == key))
317	            .map(|diagnostic| Diagnostic { affects: vec![key.to_owned()], ..diagnostic.clone() })
318	            .collect();
319	        Some(ComponentAnswer { key: key.to_owned(), entry, diagnostics })
320	    }
321	
322	    /// How many components this lazy revision indexed, how many it has resolved, and how many dependency declaration
323	    /// files it has loaded.
324	    pub(crate) fn lazy_counts(&self) -> Option<(usize, usize, usize)> {
325	        let lazy = self.lazy.as_ref()?;
326	        let loaded = lazy.engine.load().layer.as_ref().map_or(0, |layer| layer.file_count());
327	        Some((lazy.by_name.values().map(Vec::len).sum(), lazy.memo.len(), loaded))
328	    }
