1045	    /// Writes `body` over `file` and gives it back the modification time it had, so its stamp is unchanged.
1046	    fn rewrite_keeping_stamp(file: &Utf8Path, body: &[u8]) {
1047	        let modified = std::fs::metadata(file).unwrap().modified().unwrap();
1048	        std::fs::write(file, body).unwrap();
