1063	        let file = |file: &str| file.rsplit('/').next().unwrap_or_default().to_owned();
1064	        let mut files: BTreeSet<String> =
1065	            ctx.member_reads.iter().map(|entry| file(std::borrow::Borrow::borrow(&entry.key().0))).collect();
1066	        files.extend(ctx.props_reads.iter().map(|entry| file(std::borrow::Borrow::borrow(&entry.key().0))));
