40	#[derive(Clone, Default)]
41	struct Answered {
42	    component: Option<Arc<SemanticComponent>>,
43	    diagnostics: Vec<Diagnostic>,
44	}
45	
46	/// What became of one request to the checker, for every caller that waited on it.
47	#[derive(Clone)]
48	enum Settled {
49	    /// The checker answered for the component: kept for the next request.
50	    Answered(Answered),
51	    /// The checker answered nothing for the component: it was unavailable, timed out or crashed
52	    /// ([`SemanticOutcome::unavailable`]), or failed on this component ([`SemanticFallback::transient`]). The
53	    /// structural props stand, with what the checker said. Never kept as the answer: it is held as a refusal
54	    /// ([`AnswerCache::degraded`]) until [`DEGRADED_RETRY`] passes or a file changes, and the request after that asks
55	    /// the checker again.
56	    Degraded(Vec<Diagnostic>),
57	    /// The checker stopped without answering.
58	    Stopped,
59	    /// The request was cancelled before the checker converted it ([`SharedPriority::cancel`]): not an answer, and not
60	    /// a checker that stopped, so a caller reads it as one still on its way.
61	    Cancelled,
62	}
