132	    /// props (Chakra's about a thousand style props each), and an answer kept with its own copies held about 6.7 MiB
133	    /// per Chakra component, so a session that answered a few hundred stories held gigabytes.
134	    fn shared(&self, component: Arc<SemanticComponent>) -> Arc<SemanticComponent> {
135	        let SemanticComponent { key, props, composes, whole } = Arc::unwrap_or_clone(component);
136	        let props = props.into_iter().map(|prop| self.props.share_arc(prop)).collect();
137	        Arc::new(SemanticComponent { key, props, composes, whole })
138	    }
139	}
