533	    /// A checker that holds every request with its priority; the test answers one or reads its priority.
534	    #[derive(Default)]
535	    struct Holding(Mutex<Vec<(String, SharedPriority, Option<Delivery>)>>);
536	
537	    impl Holding {
538	        /// The key, priority now and whether it was cancelled, of every request in the order asked.
539	        fn asked(&self) -> Vec<(String, Priority, bool)> {
540	            let held = self.0.lock().unwrap();
541	            held.iter().map(|(key, priority, _)| (key.clone(), priority.get(), priority.is_cancelled())).collect()
542	        }
543	
544	        /// What the worker does when it takes request `n` to convert it.
545	        fn start(&self, n: usize) {
546	            assert!(self.0.lock().unwrap()[n].1.start());
547	        }
548	
549	        fn answer(&self, n: usize) {
550	            let (key, delivery) = {
551	                let mut held = self.0.lock().unwrap();
552	                (held[n].0.clone(), held[n].2.take().unwrap())
553	            };
554	            let outcome =
555	                SemanticOutcome { components: vec![(*component(&key, &["label"])).clone()], ..Default::default() };
556	            delivery.deliver(Some(outcome));
557	        }
558	    }
559	
560	    impl SemanticProvider for Holding {
561	        fn request(&self, targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome> {
562	            let (sender, receiver) = std::sync::mpsc::channel();
563	            let delivery = Delivery::new(move |outcome| {
564	                if let Some(outcome) = outcome {
565	                    sender.send(outcome).ok();
566	                }
567	            });
568	            self.request_at(targets, SharedPriority::new(Priority::Interactive), delivery);
569	            receiver
570	        }
571	
572	        fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
573	            let key = targets.into_iter().next().unwrap().key;
574	            self.0.lock().unwrap().push((key, priority, Some(delivery)));
575	        }
576	    }
577	
578	    fn session(files: &[(&str, &str)]) -> (tempfile::TempDir, Arc<crate::pipeline::WatchSession>, Arc<Holding>) {
579	        let dir = tempfile::tempdir().unwrap();
580	        let root = camino::Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
581	        for (name, source) in files {
582	            std::fs::write(root.join(name), source).unwrap();
583	        }
584	        let checker = Arc::new(Holding::default());
585	        let options = crate::pipeline::PipelineOptions { src_dirs: vec![root], ..Default::default() };
586	        let session =
587	            crate::pipeline::WatchSession::lazy(options).with_semantic(checker.clone(), Duration::from_secs(60));
588	        drop(session.initialize());
589	        (dir, Arc::new(session), checker)
590	    }
591	
592	    const BUTTON: &str = "export function Button(props: { label: string }) { return null; }";
593	    const CARD: &str = "export function Card(props: { title: string }) { return null; }";
594	
595	    /// A prefetch of a story the client navigated away from is cancelled, so the checker drops it before converting it;
596	    /// the next request of that component asks again rather than joining it. A prefetch a story joined is waited for
597	    /// and is not cancelled. On the base nothing could cancel a request.
598	    #[test]
599	    fn a_request_for_a_component_nobody_shows_is_dropped_before_conversion() {
600	        let (_dir, session, checker) = session(&[("Button.tsx", BUTTON), ("Card.tsx", CARD)]);
601	        drop(session.components_as_neighbours(&["Button".to_string(), "Card".to_string()]));
602	        let story = {
603	            let session = session.clone();
604	            std::thread::spawn(move || session.component("Card").unwrap())
605	        };
606	        while checker.asked()[1].1 != Priority::Interactive {
607	            std::thread::yield_now();
608	        }
609	
610	        session.cancel_components(&["Button".to_string(), "Card".to_string()]);
611	
612	        assert_eq!(
613	            checker.asked(),
614	            [("Button".to_string(), Priority::Neighbour, true), ("Card".to_string(), Priority::Interactive, false)]
615	        );
616	        checker.answer(1);
617	        assert!(story.join().unwrap().entry.props.contains_key("label"));
618	        drop(session.components_as_neighbours(&["Button".to_string()]));
619	        assert_eq!(checker.asked().len(), 3, "a cancelled request is not joined");
620	        assert_eq!(checker.asked()[2], ("Button".to_string(), Priority::Neighbour, false));
621	    }
622	
623	    /// A neighbour request the checker already took is converted whatever the client shows now: a cancel leaves it
624	    /// registered, so a request for the component joins it, and its one delivery settles both callers. On the base the
625	    /// cancel removed the entry and the second request started a second conversion.
626	    #[test]
627	    fn a_request_being_converted_survives_a_cancel_and_is_joined() {
628	        let (_dir, session, checker) = session(&[("Button.tsx", BUTTON)]);
629	        drop(session.components_as_neighbours(&["Button".to_string()]));
630	        checker.start(0);
631	
632	        session.cancel_components(&["Button".to_string()]);
633	        let story = {
634	            let session = session.clone();
635	            std::thread::spawn(move || session.component("Button").unwrap())
636	        };
637	        while checker.asked()[0].1 != Priority::Interactive {
638	            std::thread::yield_now();
639	        }
640	
641	        assert_eq!(checker.asked(), [("Button".to_string(), Priority::Interactive, false)]);
642	        checker.answer(0);
643	        assert!(story.join().unwrap().entry.props.contains_key("label"));
644	        assert_eq!(checker.asked().len(), 1, "one conversion served both");
645	    }
646	
647	    /// A checker that drops each request as cancelled the moment it is asked: a cancel that lands between a caller
648	    /// registering its request and reading it.
649	    struct CancelsAtOnce;
650	
651	    impl SemanticProvider for CancelsAtOnce {
652	        fn request(&self, _targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome> {
653	            std::sync::mpsc::channel().1
654	        }
655	
656	        fn request_at(&self, _targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
657	            assert!(priority.cancel());
658	            drop(delivery);
659	        }
660	    }
661	
662	    /// A cancelled request is not a checker that stopped: its caller is told the answer is still to come, with no
663	    /// warning.
664	    #[test]
665	    fn a_cancelled_request_is_not_reported_as_a_stopped_checker() {
666	        let dir = tempfile::tempdir().unwrap();
667	        std::fs::write(dir.path().join("Button.tsx"), BUTTON).unwrap();
668	        let root = camino::Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
669	        let options = crate::pipeline::PipelineOptions { src_dirs: vec![root], ..Default::default() };
670	        let session = crate::pipeline::WatchSession::lazy(options)
671	            .with_semantic(Arc::new(CancelsAtOnce), Duration::from_secs(60));
672	        drop(session.initialize());
673	
674	        let answer = session.components_as_neighbours(&["Button".to_string()]).remove(0).unwrap();
675	
676	        let messages: Vec<&str> = answer.diagnostics.iter().map(|d| d.message.as_str()).collect();
677	        assert_eq!(messages, [CHECKER_PENDING]);
678	    }
679	
680	    /// Refusals for keys never asked again do not pile up: the map holds at most [`DEGRADED_HELD`], the expired ones go
681	    /// first and then the oldest, and a fresh refusal is never dropped for an expired one. On the base an expired
682	    /// refusal went only when its own key was asked again.
683	    #[test]
684	    fn refusals_for_keys_never_asked_again_are_bounded() {
685	        let mut cache = AnswerCache::default();
686	        let start = Instant::now();
687	        let key = |n: usize| (format!("C{n}"), 0_u64);
688	        for n in 0..DEGRADED_HELD {
689	            cache.hold_degraded(key(n), start, Vec::new());
690	        }
691	        assert_eq!(cache.degraded.len(), DEGRADED_HELD);
692	        let later = start + DEGRADED_RETRY;
693	        cache.hold_degraded(key(DEGRADED_HELD), later, Vec::new());
694	        assert_eq!(cache.degraded.len(), 1, "every expired refusal went");
695	        for n in 1..=DEGRADED_HELD {
696	            cache.hold_degraded(key(DEGRADED_HELD + n), later + Duration::from_millis(n as u64), Vec::new());
697	        }
698	        assert_eq!(cache.degraded.len(), DEGRADED_HELD, "never more than the bound");
699	        assert!(!cache.degraded.contains_key(&key(DEGRADED_HELD)), "the oldest fresh one went");
700	        assert!(cache.degraded.contains_key(&key(2 * DEGRADED_HELD)), "the newest stays");
701	    }
702	
703	    /// What [`Replies`] answers while the checker has not recovered.
704	    #[derive(Clone, Copy, Debug)]
705	    enum Reply {
706	        /// `SemanticOutcome::unavailable`: no checker, a timeout, a crash.
707	        Down,
708	        /// A transient fallback for the component: the checker rejected a request (it panicked or stopped).
709	        Rejected,
710	        /// A fallback that is the checker's verdict about the component.
711	        Verdict,
712	        /// An outcome with no entry for the component and a warning, which marks it (and another) as not asked: a run
713	        /// past its heap budget.
714	        OverBudget,
715	        /// An outcome with a warning and no entry or mark for the component: the checker's answer is the structural
716	        /// one.
717	        Absent,
718	    }
719	
720	    /// A checker that answers every request at once with `reply`, or with `label` and `size` once it has `recovered`,
721	    /// and counts the requests.
722	    struct Replies {
723	        reply: Reply,
724	        recovered: std::sync::atomic::AtomicBool,
725	        asked: std::sync::atomic::AtomicUsize,
726	    }
727	
728	    impl SemanticProvider for Replies {
729	        fn request(&self, _targets: Vec<SemanticTarget>) -> std::sync::mpsc::Receiver<SemanticOutcome> {
730	            std::sync::mpsc::channel().1
731	        }
732	
733	        fn request_at(&self, targets: Vec<SemanticTarget>, _priority: SharedPriority, delivery: Delivery) {
734	            use std::sync::atomic::Ordering::SeqCst;
735	            self.asked.fetch_add(1, SeqCst);
736	            let key = targets.into_iter().next().unwrap().key;
737	            let fallback = |transient| SemanticFallback { key: key.clone(), reason: "why".to_string(), transient };
738	            let warning = Diagnostic::new(DiagnosticSeverity::Warning, DiagnosticCode::SemanticBackend, "over budget");
739	            let outcome = match (self.recovered.load(SeqCst), self.reply) {
740	                (true, _) => SemanticOutcome {
741	                    components: vec![(*component(&key, &["label", "size"])).clone()],
742	                    ..Default::default()
743	                },
744	                (false, Reply::Down) => SemanticOutcome::unavailable("no tsc in this test"),
745	                (false, Reply::Rejected) => SemanticOutcome { fallbacks: vec![fallback(true)], ..Default::default() },
746	                (false, Reply::Verdict) => SemanticOutcome { fallbacks: vec![fallback(false)], ..Default::default() },
747	                (false, Reply::OverBudget) => {
748	                    let mut outcome = SemanticOutcome { diagnostics: vec![warning], ..Default::default() };
749	                    outcome.leave_unasked([key.clone(), "Other".to_owned()]);
750	                    outcome
751	                }
752	                (false, Reply::Absent) => {
753	                    let mut outcome = SemanticOutcome { diagnostics: vec![warning], ..Default::default() };
754	                    outcome.leave_unasked(["Other".to_owned()]);
755	                    outcome
756	                }
757	            };
758	            delivery.deliver(Some(outcome));
759	        }
760	    }
761	
762	    /// A request the checker answered with nothing (down, or failed on the component) is refused again without asking
763	    /// it until `DEGRADED_RETRY` passes or a file changes, each answer still carrying what it said; then it is asked
764	    /// again, and a recovered checker's answer replaces the structural one; a run that left the component unasked once
765	    /// its heap passed the budget is refused the same way. A verdict, or an outcome with no entry and no mark for the
766	    /// component, is the checker's answer and is kept, even past the retry. On the base the down checker was asked
767	    /// by every request, a rejected fallback was kept as the answer, and an absent entry was asked by every request.
768	    #[test]
769	    fn a_checker_that_answered_nothing_is_asked_again_only_after_the_retry_or_an_edit() {
