"""Find comment blocks with history phrasing; 'show' prints the tail from the phrase, 'cut' removes it and re-fills."""
import re
import sys
import textwrap

PAT = re.compile(r'(On the base|on the base|[Bb]efore this (change|PR)|was previously)')
LINE = re.compile(r'^(\s*)(//[/!]?)( |$)')


def blocks(lines):
    i = 0
    while i < len(lines):
        m = LINE.match(lines[i])
        if not m:
            i += 1
            continue
        ind, mk = m.group(1), m.group(2)
        j = i
        while j < len(lines):
            m2 = LINE.match(lines[j])
            if not m2 or m2.group(1) != ind or m2.group(2) != mk:
                break
            j += 1
        yield i, j, ind, mk
        i = j


def paragraphs(lines, i, j, ind, mk):
    paras, cur = [], []
    for line in lines[i:j]:
        body = line[len(ind) + len(mk):].strip()
        if body == '':
            paras.append(cur)
            cur = []
        else:
            cur.append(body)
    paras.append(cur)
    return [' '.join(p) for p in paras]


def main():
    mode = sys.argv[1]
    for f in sys.argv[2:]:
        lines = open(f).read().split('\n')
        out, last = [], 0
        for i, j, ind, mk in list(blocks(lines)):
            paras = paragraphs(lines, i, j, ind, mk)
            if not any(PAT.search(p) for p in paras):
                continue
            if mode == 'show':
                for p in paras:
                    m = PAT.search(p)
                    if m:
                        print(f'--- {f}:{i + 1}: ...{p[m.start():]}')
                continue
            new = []
            for p in paras:
                m = PAT.search(p)
                if m:
                    # The history sentence runs to the end of the paragraph.
                    start = p.rfind('. ', 0, m.start())
                    p = p[:start + 1].strip() if start >= 0 else ''
                new.append(p)
            width = 120 - len(ind) - len(mk) - 1
            rendered = []
            for k, p in enumerate(new):
                if p == '' and k not in (0,) and k != len(new) - 1:
                    rendered.append(ind + mk)
                    continue
                if p == '':
                    continue
                rendered.extend(ind + mk + ' ' + w for w in textwrap.wrap(p, width, break_long_words=False,
                                                                         break_on_hyphens=False))
            out.extend(lines[last:i])
            out.extend(rendered)
            last = j
        if mode == 'cut':
            out.extend(lines[last:])
            open(f, 'w').write('\n'.join(out))


main()

