/// The same namespace member behind a barrel whose first `export *` target could not be read: the walk finds
/// `Menubar.Menu` in the next target, and `ComponentProps<typeof Primitive.Menu>` reads it there, with the warning.
#[test]
fn component_props_reads_a_namespace_member_found_past_an_unreadable_star_target() {
    let (_tmp, root) = project(&[
        ("node_modules/star-kit/package.json", r#"{ "name": "star-kit", "version": "1.0.0", "types": "index.d.ts" }"#),
        ("node_modules/star-kit/index.d.ts", "export * from './first';\nexport * from './bar';\n"),
        ("node_modules/star-kit/bar.d.ts", "import * as Menu from './menu';\nexport { Menu as Menubar };\n"),
        (
            "node_modules/star-kit/menu.d.ts",
            "import * as react_jsx_runtime from 'react/jsx-runtime';\n\
             type ScopedProps<P> = P & { __scopeMenubar?: string };\n\
             interface MenuProps { value?: string; children?: string }\n\
             declare const Menu: { (props: ScopedProps<MenuProps>): react_jsx_runtime.JSX.Element; displayName: string };\n\
             export { Menu };\n",
        ),
        (
            "src/Menubar.tsx",
            "import * as React from 'react';\nimport { Menubar as Primitive } from 'star-kit';\n\
             export function MenubarMenu(props: React.ComponentProps<typeof Primitive.Menu>) { return null; }\n",
        ),
    ]);
    let first = root.join("node_modules/star-kit/first.d.ts");
    std::fs::write(&first, [0xff; 8]).unwrap();

    let output = extract(&options(&root, true));
    assert_eq!(
        prop_types(&output, "MenubarMenu"),
        [
            ("__scopeMenubar".into(), "string".into()),
            ("children".into(), "string".into()),
            ("value".into(), "string".into()),
        ]
    );
    let io = |d: &&Diagnostic| d.code == DiagnosticCode::IoError && d.file.as_deref() == Some(first.as_str());
    assert_eq!(output.diagnostics.iter().filter(io).count(), 1, "{:?}", output.diagnostics);
}

