import sys

p = sys.argv[1]
s = open(p).read()


def rep(old, new, count=1):
    global s
    if s.count(old) != count:
        sys.exit(f'count {s.count(old)}: {old[:90]!r}')
    s = s.replace(old, new)


rep('''struct Totals {
    files: usize,
    react_files: usize,
    exports: usize,
    resolutions: usize,
    unresolved: usize,
}''', '''struct Totals {
    files: usize,
    react_files: usize,
    exports: usize,
    /// Partial mappings a layer added or changed from the chain's ([`DependencyLayer::partial_exports`]): the resolver
    /// reads them, so a load that only adds one is a change.
    partial_exports: usize,
    resolutions: usize,
    unresolved: usize,
}''')
rep('''    /// Whether `other`, a layer this one was extended from, resolves every name the way this one does: extending only
    /// adds, so equal counts mean nothing was added.
    pub(crate) fn resolves_like(&self, other: &DependencyLayer) -> bool {
        let (a, b) = (self.totals, other.totals);
        a.files == b.files
            && a.react_files == b.react_files
            && a.exports == b.exports''', '''    /// Whether `other`, a layer this one was extended from, resolves every name the way this one does: extending only
    /// adds, so equal counts mean nothing was added. A partial mapping counts only where it differs from the chain's.
    pub(crate) fn resolves_like(&self, other: &DependencyLayer) -> bool {
        let (a, b) = (self.totals, other.totals);
        a.files == b.files
            && a.react_files == b.react_files
            && a.exports == b.exports
            && a.partial_exports == b.partial_exports''')
rep('''    let files: FxHashSet<PathKey> = files.into_iter().collect();
    let below = parent.as_ref().map(|layer| layer.totals).unwrap_or_default();''', '''    let files: FxHashSet<PathKey> = files.into_iter().collect();
    // A walk that found the mapping the chain already holds adds nothing the resolver reads.
    let partial_exports: FxHashMap<_, _> = loader
        .partial_exports
        .into_iter()
        .filter(|(key, found)| {
            parent.as_ref().and_then(|layer| layer.chain().find_map(|layer| layer.partial_exports.get(key))) != Some(found)
        })
        .collect();
    let below = parent.as_ref().map(|layer| layer.totals).unwrap_or_default();''')
rep('''        exports: below.exports + exports.len(),''', '''        exports: below.exports + exports.len(),
        partial_exports: below.partial_exports + partial_exports.len(),''')
rep('''        partial_exports: loader.partial_exports.into_iter().collect(),''', '''        partial_exports,''')
open(p, 'w').write(s)

