// A walk past a file that could not be read answers more once it is followed again: until then the
// answer holds only provisionally, and never in the memo an edit carries over.
if !unread.is_empty() {
    match engine.layer.as_ref().and_then(|layer| layer.footprint(&unread)) {
        Some(footprint) => drop(lazy.provisional.insert(id.clone(), (resolved.clone(), footprint))),
        // A file one of the walks could not read was read since in this same layer, so the walk is due:
        // this pass already asked for it (`missing == asked_for`) and the load left it as it was. The
        // answer and its warnings both come from `engine`; held nowhere, the next request asks again.
        None => {}
    }
    return Some((resolved, engine.layer.clone()));
}

